import { Component, Input } from '@angular/core';

@Component({
  selector: 'app-datepicker',
  templateUrl: './datepicker.component.html',
  styleUrls: ['./datepicker.component.css']
})
export class DatepickerComponent {
	@Input() dateValue : Date = new Date();

	dateValueString : string = this.formatDateToDDMMYYYY(this.dateValue);
	@Input() isReadOnly: boolean = false;
	@Input() labelString: string = "Date";
	@Input() showLabel: boolean = true;
	@Input() includeOuterDiv: boolean = true;

	formatDateToDDMMYYYY(date : Date) {
		// Get day, month, and year components
		const day = date.getDate();
		const month = date.getMonth() + 1; // Months are zero-based, so add 1
		const year = date.getFullYear();

		// Ensure two-digit format for day and month
		const formattedDay = day < 10 ? '0' + day : day;
		const formattedMonth = month < 10 ? '0' + month : month;

		// Combine components in "dd/mm/yyyy" format
		const formattedDate = `${formattedDay}/${formattedMonth}/${year}`;

		return formattedDate;
	  }
}

<div *ngIf="includeOuterDiv" class="default-input d-flex flex-wrap">
    <label *ngIf="showLabel" for="date" class="default-label"> Date </label>
    <input
        type="text"
        [value]="dateValueString"
        readonly
        class="no-style-input inner-input composed-input primary d-flex"
        placeholder="Select Date"
    />
</div>
<label *ngIf="showLabel && !includeOuterDiv" for="date" class="default-label"> Date </label>
<input
    *ngIf="!includeOuterDiv"
    type="text"
    [value]="dateValueString"
    readonly
    class="no-style-input inner-input composed-input primary d-flex"
    placeholder="Select Date"
/>
